/**
 * W3C Web Authentication Level 3 test vectors (Recommendation, 25 August 2026),
 * section 16: https://www.w3.org/TR/webauthn-3/#sctn-test-vectors
 *
 * Copied verbatim (hex, lowercase) from the REC: every `name = h'...'` line of
 * 16.2, 16.4, 16.5, 16.6, 16.10 and 16.11, split into the registration and
 * authentication halves. Comment-only lines and the `2^p - 1` RSA private key
 * primes of 16.10 are not copied. Each vector keeps its section URL.
 * All vectors use RP ID example.org, origin https://example.org and, where
 * present, topOrigin https://example.com.
 *
 * Test support only; never shipped.
 *
 * @package MagicAuth\Tests
 */

declare( strict_types=1 );

namespace MagicAuth\Tests\Support;

final class Fixtures {

	public const SOURCE     = 'https://www.w3.org/TR/webauthn-3/#sctn-test-vectors';
	public const RP_ID      = 'example.org';
	public const ORIGIN     = 'https://example.org';
	public const TOP_ORIGIN = 'https://example.com';

	/**
	 * @return array{title:string,source:string,registration:array<string,string>,authentication:array<string,string>}
	 */
	public static function vector( string $id ): array {
		if ( ! isset( self::VECTORS[ $id ] ) ) {
			throw new \InvalidArgumentException( 'Fixtures: unknown vector ' . $id );
		}
		return self::VECTORS[ $id ];
	}

	/** Raw bytes of one value, e.g. bin( '16.2', 'authentication', 'signature' ). */
	public static function bin( string $id, string $ceremony, string $name ): string {
		$hex = self::vector( $id )[ $ceremony ][ $name ] ?? null;
		if ( null === $hex ) {
			throw new \InvalidArgumentException( "Fixtures: no {$ceremony}.{$name} in {$id}" );
		}
		return (string) hex2bin( $hex );
	}

	/** @return array<int,string> */
	public static function ids(): array {
		return array_keys( self::VECTORS );
	}

